import{_ as i,H as l,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const R=JSON.parse(`{"title":"O'ReillyMedia,Inc.介绍","description":"","frontmatter":{},"headers":[],"relativePath":"Rust程序设计（第2版）/O'ReillyMedia,Inc.介绍.md","filePath":"Rust程序设计（第2版）/O'ReillyMedia,Inc.介绍.md","lastUpdated":1795533925000}`),t={name:"Rust程序设计（第2版）/O'ReillyMedia,Inc.介绍.md"};function r(p,e,s,d,o,_){return l(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="o-reillymedia-inc-介绍" tabindex="-1">O&#39;ReillyMedia,Inc.介绍 <a class="header-anchor" href="#o-reillymedia-inc-介绍" aria-label="Permalink to &quot;O&#39;ReillyMedia,Inc.介绍&quot;">​</a></h1><p>O&#39;Reilly 以“分享创新知识、改变世界”为己任。40 多年来我们一直向企业、个人提供成功所必需之技能及思想，激励他们创新并做得更好。</p><p>O&#39;Reilly 业务的核心是独特的专家及创新者网络，众多专家及创新者通过我们分享知识。我们的在线学习（Online Learning）平台提供独家的直播培训、互动学习、认证体验、图书及视频等，使客户更容易获取业务成功所需的专业知识。几十年来 O&#39;Reilly 图书一直被视为学习开创未来之技术的权威资料。我们所做的一切是为了帮助各领域的专业人士学习最佳实践，发现并塑造科技行业未来的新趋势。</p><p>我们的客户渴望做出推动世界前进的创新之举，我们希望能助他们一臂之力。</p><p>业界评论</p><ul><li><p>“O&#39;Reilly Radar 博客有口皆碑。”——Wired</p></li><li><p>“O&#39;Reilly 凭借一系列非凡想法（真希望当初我也想到了）建立了数百万美元的业务。”——Business 2.0</p></li><li><p>“O&#39;Reilly Conference 是聚集关键思想领袖的绝对典范。”——CRN</p></li><li><p>“一本 O&#39;Reilly 的书就代表一个有用、有前途、需要学习的主题。”——Irish Times</p></li><li><p>“Tim 是位特立独行的商人，他不光放眼于最长远、最广阔的领域，并且切实地按照 YogiBerra 的建议去做了：‘如果你在路上遇到岔路口，那就走小路。’回顾过去，Tim 似乎每一次</p></li><li><p>都选择了小路，而且有几次都是一闪即逝的机会，尽管大路也不错。”——Linux Journal</p></li></ul>',6)])])}const y=i(t,[["render",r]]);export{R as __pageData,y as default};
